BEGIN;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
DO $test$
DECLARE c uuid:=gen_random_uuid();a uuid:=gen_random_uuid();o uuid:=gen_random_uuid();u uuid:=gen_random_uuid();late_u uuid:=gen_random_uuid();expired_u uuid:=gen_random_uuid();e uuid:=gen_random_uuid();tier uuid:=gen_random_uuid();paid uuid:=gen_random_uuid();guest uuid:=gen_random_uuid();free_ticket uuid:=gen_random_uuid();late_ticket uuid:=gen_random_uuid();late_guest uuid:=gen_random_uuid();expired_ticket uuid:=gen_random_uuid();move_id uuid:=gen_random_uuid();cancel_id uuid:=gen_random_uuid();r jsonb;before_wallet numeric;before_hp integer;before_sold integer;bad_event uuid:=gen_random_uuid();bad_ticket uuid:=gen_random_uuid();
 copy jsonb:='{"event_cancelled_title":"Cancelled: {title}","event_cancelled_body":"{title} cancelled. {reason}","event_rescheduled_title":"New date: {title}","event_rescheduled_body":"{title}: {date}, {venue}. {reason}"}';args jsonb;
BEGIN
 INSERT INTO campuses(id,name,slug) VALUES(c,'[AUDIT rollback] Event exceptions '||c,'audit-exceptions-'||c);
 INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT id,'audit-exception-'||id||'@example.invalid','{}'::jsonb FROM unnest(ARRAY[a,o,u,late_u,expired_u])id;
 UPDATE profiles SET campus_id=c WHERE id IN(a,o,u,late_u,expired_u);
 UPDATE profiles SET role='admin' WHERE id=a;UPDATE profiles SET role='event_organizer' WHERE id=o;
 INSERT INTO feature_flags(feature_name,campus_id,is_active) VALUES('events',c,true),('hp_multiplier',c,false);
 INSERT INTO events(id,title,slug,location,starts_at,ends_at,capacity,campus_id,organizer_id,is_published,hp_per_attendee) VALUES(e,'[AUDIT rollback] Event exceptions','audit-'||e,'Old hall',now()+interval '1 day',now()+interval '2 days',100,c,o,true,50);
 INSERT INTO event_ticket_tiers(id,event_id,name,price_naira,capacity,sold_count,campus_id) VALUES(tier,e,'Regular',100,100,6,c);
 INSERT INTO hg_internal.event_organizer_terms(tier_id,event_id,organizer_amount,updated_by) VALUES(tier,e,80,a);
 INSERT INTO event_tickets(id,event_id,tier_id,user_id,status,payment_status,campus_id,price_naira,wallet_amount_used,hp_amount_paid,qr_expires_at) VALUES(paid,e,tier,u,'confirmed','paid',c,100,100,5,now()+interval '2 days 1 hour');
 INSERT INTO event_tickets(id,event_id,tier_id,is_guest,guest_email,status,payment_status,campus_id,price_naira,card_amount_used,payment_reference) VALUES(guest,e,tier,true,'audit-event-guest@example.invalid','confirmed','paid',c,100,100,'audit-paid-'||guest),(late_guest,e,tier,true,'audit-event-late@example.invalid','pending_payment','pending',c,100,100,'audit-late-'||late_guest);
 INSERT INTO payments(ticket_id,provider,reference,amount,status,campus_id) VALUES(guest,'paystack','audit-paid-'||guest,100,'paid',c);
 INSERT INTO event_tickets(id,event_id,tier_id,is_guest,guest_email,status,payment_status,campus_id) VALUES(free_ticket,e,tier,true,'audit-free@example.invalid','confirmed','not_required',c);
 INSERT INTO event_tickets(id,event_id,tier_id,user_id,status,payment_status,campus_id,price_naira,wallet_amount_used,hp_amount_paid,card_amount_used,payment_reference,payment_expires_at) VALUES(late_ticket,e,tier,late_u,'pending_payment','pending',c,100,20,5,80,'audit-late-'||late_ticket,now()+interval '30 minutes'),(expired_ticket,e,tier,expired_u,'pending_payment','pending',c,100,30,7,70,'audit-expired-'||expired_ticket,now()-interval '1 minute');
 PERFORM hg_release_expired_event_reservation(expired_ticket);
 args:=jsonb_build_object('expected_updated_at',(SELECT updated_at FROM events WHERE id=e),'reason','The venue has requested a later date.','starts_at',now()+interval '3 days','ends_at',now()+interval '4 days','location','New hall','_copy',copy);
 BEGIN UPDATE events SET metadata=coalesce(metadata,'{}')||'{"lifecycle_status":"cancelled"}' WHERE id=e;RAISE EXCEPTION 'direct cancellation metadata accepted';EXCEPTION WHEN check_violation THEN IF SQLERRM<>'HG_EVENT_CHANGE_USE_WORKSPACE' THEN RAISE;END IF;END;
 BEGIN UPDATE events SET location='Silently changed hall' WHERE id=e;RAISE EXCEPTION 'legacy editor changed booked event';EXCEPTION WHEN check_violation THEN IF SQLERRM<>'HG_EVENT_CHANGE_USE_WORKSPACE' THEN RAISE;END IF;END;
 r:=hg_change_event_operation(a,e,move_id,'reschedule',args);
 IF r->>'action'<>'reschedule' OR (SELECT location FROM events WHERE id=e)<>'New hall' THEN RAISE EXCEPTION 'reschedule did not persist';END IF;
 IF (SELECT qr_expires_at FROM event_tickets WHERE id=paid)<>(SELECT ends_at+interval '1 hour' FROM events WHERE id=e) THEN RAISE EXCEPTION 'QR expiry did not follow date';END IF;
 IF (SELECT wallet_amount_used FROM event_tickets WHERE id=paid)<>100 OR (SELECT organizer_amount FROM hg_internal.event_ticket_earnings WHERE ticket_id=paid)<>80 THEN RAISE EXCEPTION 'reschedule rewrote financial snapshot';END IF;
 IF (SELECT count(*) FROM notifications WHERE user_id=u AND reference_id=move_id)<>3 OR NOT EXISTS(SELECT 1 FROM notification_deliveries WHERE dispatch_payload->>'kind'='event_status_email' AND dispatch_payload->>'ticket_id'=guest::text) THEN RAISE EXCEPTION 'attendee notices missing';END IF;
 r:=hg_change_event_operation(a,e,move_id,'reschedule',args);IF NOT (r->>'replayed')::boolean THEN RAISE EXCEPTION 'reschedule replay missing';END IF;
 BEGIN PERFORM hg_change_event_operation(a,e,move_id,'reschedule',args||'{"location":"Changed intent"}');RAISE EXCEPTION 'changed replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM hg_change_event_operation(a,e,gen_random_uuid(),'reschedule',args||jsonb_build_object('expected_updated_at',now()-interval '1 year'));RAISE EXCEPTION 'stale operation accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 args:=jsonb_build_object('expected_updated_at',(SELECT updated_at FROM events WHERE id=e),'reason','The event has been cancelled by the host.','_copy',copy);
 r:=hg_change_event_operation(a,e,cancel_id,'cancel',args);
 IF (r->>'refunds')::integer<>2 OR (r->>'free_cancelled')::integer<>1 OR (r->>'awaiting_payment')::integer<>2 THEN RAISE EXCEPTION 'cancellation counts wrong: %',r;END IF;
 IF (SELECT balance FROM wallets WHERE user_id=u)<>100 OR (SELECT hp_balance FROM profiles WHERE id=u)<>5 THEN RAISE EXCEPTION 'member refund not restored';END IF;
 IF (SELECT state FROM hg_internal.event_ticket_refunds WHERE ticket_id=guest)<>'queued' THEN RAISE EXCEPTION 'guest gateway refund not queued';END IF;
 r:=hg_change_event_operation(a,e,cancel_id,'cancel',args);IF NOT (r->>'replayed')::boolean OR (SELECT balance FROM wallets WHERE user_id=u)<>100 THEN RAISE EXCEPTION 'cancel replay duplicated refund';END IF;
 BEGIN INSERT INTO event_tickets(event_id,is_guest,guest_email,status,payment_status,campus_id) VALUES(e,true,'audit-new@example.invalid','confirmed','not_required',c);RAISE EXCEPTION 'cancelled event sold ticket';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HG_EVENT_ALREADY_CANCELLED' THEN RAISE;END IF;END;
 BEGIN PERFORM hg_admit_event_ticket(e,free_ticket,o,NULL,c,50);RAISE EXCEPTION 'cancelled event admitted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Event not available' THEN RAISE;END IF;END;
 -- Deactivation cannot erase an already approved refund obligation.
 UPDATE profiles SET is_active=false,role='student',campus_id=NULL WHERE id=a;
 PERFORM hg_pay_event_with_delivery(late_ticket,'paystack','audit-late-'||late_ticket,80,'{}');
 PERFORM hg_pay_event_with_delivery(late_ticket,'paystack','audit-late-'||late_ticket,80,'{}');
 IF (SELECT balance FROM wallets WHERE user_id=late_u)<>100 OR (SELECT hp_balance FROM profiles WHERE id=late_u)<>5 OR (SELECT payment_status FROM event_tickets WHERE id=late_ticket)<>'refunded' THEN RAISE EXCEPTION 'late member payment not refunded exactly once';END IF;
 PERFORM hg_pay_event_with_delivery(late_guest,'paystack','audit-late-'||late_guest,100,'{}');
 PERFORM hg_pay_event_with_delivery(late_guest,'paystack','audit-late-'||late_guest,100,'{}');
 IF (SELECT count(*) FROM hg_internal.event_ticket_refunds WHERE ticket_id=late_guest)<>1 OR (SELECT payment_status FROM event_tickets WHERE id=late_guest)<>'refund_pending' THEN RAISE EXCEPTION 'late guest payment did not queue exactly one refund';END IF;
 SELECT balance INTO before_wallet FROM wallets WHERE user_id=expired_u;SELECT hp_balance INTO before_hp FROM profiles WHERE id=expired_u;SELECT sold_count INTO before_sold FROM event_ticket_tiers WHERE id=tier;
 PERFORM hg_pay_event_with_delivery(expired_ticket,'paystack','audit-expired-'||expired_ticket,70,'{}');
 PERFORM hg_pay_event_with_delivery(expired_ticket,'paystack','audit-expired-'||expired_ticket,70,'{}');
 IF (SELECT balance FROM wallets WHERE user_id=expired_u)<>before_wallet+70 OR (SELECT hp_balance FROM profiles WHERE id=expired_u)<>before_hp OR (SELECT sold_count FROM event_ticket_tiers WHERE id=tier)<>before_sold OR (SELECT amount FROM hg_internal.event_ticket_refunds WHERE ticket_id=expired_ticket)<>70 THEN RAISE EXCEPTION 'expired late payment duplicated wallet/HP/capacity restoration';END IF;
 -- Financial errors must roll back the whole operation, including metadata.
 UPDATE profiles SET is_active=true,role='admin',campus_id=c WHERE id=a;
 INSERT INTO events(id,title,slug,location,starts_at,ends_at,campus_id,is_published) VALUES(bad_event,'[AUDIT rollback] Bad breakdown','audit-'||bad_event,'Hall',now()+interval '1 day',now()+interval '2 days',c,true);
 INSERT INTO event_tickets(id,event_id,user_id,status,payment_status,campus_id,price_naira,wallet_amount_used) VALUES(bad_ticket,bad_event,u,'confirmed','paid',c,100,10);
 BEGIN PERFORM hg_change_event_operation(a,bad_event,gen_random_uuid(),'cancel',args||jsonb_build_object('expected_updated_at',(SELECT updated_at FROM events WHERE id=bad_event)));RAISE EXCEPTION 'bad financial cancellation accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Ticket financial breakdown invalid' THEN RAISE;END IF;END;
 IF (SELECT metadata->>'lifecycle_status' FROM events WHERE id=bad_event)='cancelled' OR EXISTS(SELECT 1 FROM hg_internal.event_ticket_refunds WHERE ticket_id=bad_ticket) THEN RAISE EXCEPTION 'failed cancellation left partial state';END IF;
 IF has_function_privilege('authenticated','hg_change_event_operation(uuid,uuid,uuid,text,jsonb)','EXECUTE') OR has_function_privilege('anon','hg_internal.queue_event_change_notices(uuid,uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'public lifecycle mutation';END IF;
END $test$;
ROLLBACK;
SELECT 'PASS reschedule, preserved ticket/earning values, member/guest notices, cancel/refund replay, denied admission/sales, late/expired payment restoration, actor deactivation and full failure rollback; fixtures rolled back' AS evidence;
